import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

public class EnumCollectionsDemo {

    public enum Permission {
        READ, WRITE, EXECUTE, DELETE, AUDIT
    }

    public enum OrderState {
        CREATED, PAID, PROCESSING, SHIPPED, DELIVERED, CANCELLED
    }

    public static void main(String[] args) {
        // 1. Bitmask operations with EnumSet
        EnumSet<Permission> userPerms = EnumSet.of(Permission.READ);
        EnumSet<Permission> adminPerms = EnumSet.allOf(Permission.class);
        EnumSet<Permission> editorPerms = EnumSet.range(Permission.READ, Permission.WRITE);

        System.out.println("User permissions: " + userPerms);
        System.out.println("Editor permissions: " + editorPerms);
        System.out.println("Admin permissions: " + adminPerms);

        // Union (OR)
        EnumSet<Permission> combined = EnumSet.copyOf(userPerms);
        combined.addAll(editorPerms);
        System.out.println("Combined: " + combined);

        // Complement (NOT)
        EnumSet<Permission> nonAdminRestricted = EnumSet.complementOf(userPerms);
        System.out.println("Permissions user lacks: " + nonAdminRestricted);

        // Ultra-fast containment check (single bitwise test)
        boolean canWrite = editorPerms.contains(Permission.WRITE);
        System.out.println("Editor can write: " + canWrite);

        // 2. High-Performance State Machine with EnumMap
        Map<OrderState, Set<OrderState>> validTransitions = new EnumMap<>(OrderState.class);

        validTransitions.put(OrderState.CREATED, EnumSet.of(OrderState.PAID, OrderState.CANCELLED));
        validTransitions.put(OrderState.PAID, EnumSet.of(OrderState.PROCESSING, OrderState.CANCELLED));
        validTransitions.put(OrderState.PROCESSING, EnumSet.of(OrderState.SHIPPED, OrderState.CANCELLED));
        validTransitions.put(OrderState.SHIPPED, EnumSet.of(OrderState.DELIVERED));
        validTransitions.put(OrderState.DELIVERED, EnumSet.noneOf(OrderState.class));
        validTransitions.put(OrderState.CANCELLED, EnumSet.noneOf(OrderState.class));

        // Test state transition validation
        OrderState current = OrderState.PAID;
        OrderState nextValid = OrderState.PROCESSING;
        OrderState nextInvalid = OrderState.DELIVERED;

        boolean isAllowed1 = validTransitions.get(current).contains(nextValid);
        boolean isAllowed2 = validTransitions.get(current).contains(nextInvalid);

        System.out.println("Transition PAID -> PROCESSING allowed: " + isAllowed1);
        System.out.println("Transition PAID -> DELIVERED allowed: " + isAllowed2);
    }
}
```

