import java.util.EnumSet;

public class RoleSecurity {
    public enum Role { GUEST, USER, MODERATOR, ADMIN, ROOT }

    public static EnumSet<Role> findRestrictedRoles(EnumSet<Role> grantedRoles) {
        if (grantedRoles == null || grantedRoles.isEmpty()) {
            return EnumSet.allOf(Role.class);
        }
        return EnumSet.complementOf(grantedRoles);
    }
}

