import java.util.EnumMap;
import java.util.EnumSet;

public class StateTransitionGuard<S extends Enum<S>> {
    private final EnumMap<S, EnumSet<S>> transitions;
    private final Class<S> enumClass;

    public StateTransitionGuard(Class<S> enumClass) {
        this.enumClass = enumClass;
        this.transitions = new EnumMap<>(enumClass);
    }

    public void addTransition(S from, S to) {
        if (from != null && to != null) {
            transitions.computeIfAbsent(from, k -> EnumSet.noneOf(enumClass)).add(to);
        }
    }

    public boolean isValid(S from, S to) {
        if (from == null || to == null) return false;
        EnumSet<S> validNext = transitions.get(from);
        return validNext != null && validNext.contains(to);
    }
}
